document.addEventListener("DOMContentLoaded",function(){const e=document.getElementById("social-media-form");e&&e.addEventListener("submit",function(e){e.preventDefault();const n=parseFloat(document.getElementById("tiktokFollowers").value)||0,t=parseFloat(document.getElementById("tiktokEngagement").value)/100||0,o=parseFloat(document.getElementById("instagramFollowers").value)||0,r=parseFloat(document.getElementById("instagramEngagement").value)/100||0,i=parseFloat(document.getElementById("youtubeSubscribers").value)||0,a=parseFloat(document.getElementById("youtubeEngagement").value)/100||0,d=parseFloat(document.getElementById("twitterFollowers").value)||0,s=document.getElementById("contentNiche").value,l=document.getElementById("audienceAge").value,g=document.getElementById("audienceLocation").value,c=parseInt(document.getElementById("monthlySponsored").value)||0,m=parseFloat(document.getElementById("avgSponsoredRate").value)||0,u="true"===document.getElementById("affiliateEnabled").value,b="true"===document.getElementById("productsEnabled").value,h=parseInt(document.getElementById("postsPerWeek").value),p=parseFloat(document.getElementById("growthRate").value)/100,f={lifestyle:1,fashion:1.4,fitness:1.2,tech:1.3,business:1.5,food:1.1,travel:1.2,education:.8,comedy:.9}[s],v={genz:.8,millennial:1.2,genx:1.4,boomer:1.1}[l],$={us:1.5,western:1.2,global:1,developing:.6}[g];let y=0;if(n>0){const e=n/1e3*15*f*v*$;y=(n>1e5?.002*n:0)+Math.min(e,.08*n)+(n>1e3?.001*n:0)}let x=0;if(o>0){const e=o/1e3*25*f*v*$;x=Math.min(e,.12*o)+(o>5e4?.003*o:0)+.005*o}let F=0;if(i>0){const e=i/1e3*35*f*v*$;F=Math.min(e,.15*i)+(i>1e3?.005*i*4.99:0)}let M=0;if(d>0){const e=d/1e3*8*f*v*$;M=Math.min(e,.04*d)}const E=c*m;let w=0;if(u){w=.008*(n+o+i+d)*f}let I=0;if(b){I=(n+o+i+d)*.001*("fashion"===s?80:"tech"===s?150:50)}const S=y+x+F+M,k=S+E+w+I,B=n+o+i+d,L=B*Math.pow(1+p,12),A=k*(L/B),C=B>0?k/B:0;let P="",T="";B<1e4?(P="🌱 Micro Creator",T="warning"):B<1e5?(P="📈 Rising Creator",T="info"):B<1e6?(P="🚀 Macro Influencer",T="success"):(P="⭐ Mega Influencer",T="success");const z=(t+r+a)/3,K=z>.05?"High":z>.03?"Good":"Needs Work";document.getElementById("social-media-result").innerHTML=`\n      <h3>📱 Social Media Earnings Analysis</h3>\n      \n      <div class="insight-cards">\n        <div class="insight-card ${T}">\n          <h6>💰 Monthly Earnings</h6>\n          <div class="big-number">$${Math.round(k).toLocaleString()}</div>\n          <p>${P}<br>\n          Annual: $${Math.round(12*k).toLocaleString()}<br>\n          $${C.toFixed(3)} per follower</p>\n        </div>\n        \n        <div class="insight-card info">\n          <h6>👥 Total Reach</h6>\n          <div class="big-number">${Math.round(B/1e3)}K</div>\n          <p>Combined followers<br>\n          ${K} engagement<br>\n          ${s} niche</p>\n        </div>\n        \n        <div class="insight-card success">\n          <h6>📈 12-Month Projection</h6>\n          <div class="big-number">$${Math.round(A).toLocaleString()}</div>\n          <p>With ${(100*p).toFixed(1)}% monthly growth<br>\n          Followers: ${Math.round(L/1e3)}K<br>\n          ${Math.round((A-k)/Math.max(k,1)*100)}% earnings increase</p>\n        </div>\n      </div>\n\n      <div style="margin-top: 2rem; padding: 1.5rem; background: #f8f9fa; border-radius: 12px;">\n        <h4>📊 Platform Breakdown & Strategy</h4>\n        \n        <div style="display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 1rem; margin-top: 1rem;">\n          ${n>0?`\n          <div style="text-align: center; padding: 1rem; background: white; border-radius: 8px; border-left: 4px solid #FF0050;">\n            <strong>📱 TikTok</strong><br>\n            ${(n/1e3).toFixed(0)}K followers<br>\n            ${(100*t).toFixed(1)}% engagement<br>\n            <strong>$${Math.round(y).toLocaleString()}/month</strong>\n          </div>\n          `:""}\n          \n          ${o>0?`\n          <div style="text-align: center; padding: 1rem; background: white; border-radius: 8px; border-left: 4px solid #E4405F;">\n            <strong>📷 Instagram</strong><br>\n            ${(o/1e3).toFixed(0)}K followers<br>\n            ${(100*r).toFixed(1)}% engagement<br>\n            <strong>$${Math.round(x).toLocaleString()}/month</strong>\n          </div>\n          `:""}\n          \n          ${i>0?`\n          <div style="text-align: center; padding: 1rem; background: white; border-radius: 8px; border-left: 4px solid #FF0000;">\n            <strong>📺 YouTube</strong><br>\n            ${(i/1e3).toFixed(0)}K subscribers<br>\n            ${(100*a).toFixed(1)}% engagement<br>\n            <strong>$${Math.round(F).toLocaleString()}/month</strong>\n          </div>\n          `:""}\n          \n          ${d>0?`\n          <div style="text-align: center; padding: 1rem; background: white; border-radius: 8px; border-left: 4px solid #1DA1F2;">\n            <strong>🐦 Twitter/X</strong><br>\n            ${(d/1e3).toFixed(0)}K followers<br>\n            <strong>$${Math.round(M).toLocaleString()}/month</strong>\n          </div>\n          `:""}\n        </div>\n        \n        <div style="margin-top: 1.5rem; display: grid; grid-template-columns: 1fr 1fr; gap: 1.5rem;">\n          <div>\n            <strong>💸 Revenue Sources:</strong><br>\n            Platform earnings: $${Math.round(S).toLocaleString()} (${(S/Math.max(k,1)*100).toFixed(1)}%)<br>\n            Sponsored content: $${Math.round(E).toLocaleString()} (${(E/Math.max(k,1)*100).toFixed(1)}%)<br>\n            Affiliate marketing: $${Math.round(w).toLocaleString()} (${(w/Math.max(k,1)*100).toFixed(1)}%)<br>\n            Product sales: $${Math.round(I).toLocaleString()} (${(I/Math.max(k,1)*100).toFixed(1)}%)\n          </div>\n          \n          <div>\n            <strong>🎯 Audience Insights:</strong><br>\n            Primary age: ${l.replace("gen","Gen ").replace("millennial","Millennial")}<br>\n            Location: ${g.toUpperCase()}<br>\n            Content niche: ${s}<br>\n            Posts/week: ${h}<br>\n            Avg engagement: ${(100*z).toFixed(1)}%<br>\n            Growth rate: ${(100*p).toFixed(1)}%/month\n          </div>\n        </div>\n        \n        <div style="margin-top: 1rem; padding: 1rem; background: ${k>=5e3?"#d4edda":k>=1e3?"#fff3cd":"#f8d7da"}; border-radius: 8px; border-left: 4px solid ${k>=5e3?"#28a745":k>=1e3?"#ffc107":"#dc3545"};">\n          <strong>💡 Monetization Strategy:</strong><br>\n          ${k>=5e3?"🎉 Excellent earning potential! Focus on premium brand partnerships, consider launching courses or coaching, and explore exclusive content offerings.":k>=1e3?"✅ Strong foundation! Diversify income streams, improve engagement rates, and start building email list for direct marketing.":"📈 Growing foundation. Focus on consistent content creation, engagement building, and platform optimization before heavy monetization focus."}<br><br>\n          \n          <strong>🚀 Optimization Tips:</strong><br>\n          • ${z<.03?"Boost engagement with more interactive content, stories, and community building":"Leverage high engagement for brand partnership negotiations"}<br>\n          • ${c<2?"Increase outreach to brands or join influencer marketing platforms":"Maintain authentic sponsored content balance"}<br>\n          • ${u?"Optimize affiliate strategy with better product selection":"Start affiliate marketing with products you genuinely use and recommend"}<br>\n          • ${h<7?"Consider increasing posting frequency for algorithm favor":"Maintain consistent posting schedule"}\n        </div>\n      </div>\n    `})});